import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.DzGOF12C.js";const q=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"심신동일론이란","slug":"심신동일론이란","link":"#심신동일론이란","children":[]},{"level":2,"title":"스마트 — 오캄의 면도날에 호소","slug":"스마트-—-오캄의-면도날에-호소","link":"#스마트-—-오캄의-면도날에-호소","children":[]},{"level":2,"title":"암스트롱 — 성향에 대한 인과적 분석","slug":"암스트롱-—-성향에-대한-인과적-분석","link":"#암스트롱-—-성향에-대한-인과적-분석","children":[]},{"level":2,"title":"파피노 — 유물론에 대한 인과논증","slug":"파피노-—-유물론에-대한-인과논증","link":"#파피노-—-유물론에-대한-인과논증","children":[]}],"relativePath":"philosophy/Philosophy-of-Mind/04. 심신동일론.md","filePath":"philosophy/Philosophy-of-Mind/04. 심신동일론.md"}'),e={name:"philosophy/Philosophy-of-Mind/04. 심신동일론.md"};function a(d,t,g,l,u,i){return r(),n("div",null,[...t[0]||(t[0]=[s('<h2 id="심신동일론이란" tabindex="-1">심신동일론이란 <a class="header-anchor" href="#심신동일론이란" aria-label="Permalink to &quot;심신동일론이란&quot;">​</a></h2><p><strong>심신동일론(mind-brain identity theory)</strong>은 마음 상태 = 두뇌 상태라고 주장한다 — 영혼 같은 비물리적 실체는 없으며, 정신적 속성은 곧 물리적 속성이라는 것. 이 이론의 발전은 뇌과학, 특히 fMRI 등을 통해 정신 상태와 두뇌 상태 사이의 <strong>상관관계(correlation)</strong>가 속속 밝혀진 데 크게 힘입었다. 어떤 두뇌 상태(예: 특정 부위 뉴런의 활성화)가 특정 마음 상태와 항상 함께 나타날 때, 이를 그 마음 상태의 <strong>신경적 상관자(neural correlate)</strong>라 부른다.</p><p>여기서 핵심 주의점: 동일론이 말하는 <strong>동일성(identity)</strong>은 엄밀한 수적 동일성(&quot;=&quot;)이지, 의미의 같음이나 번역 가능성이 아니다. &quot;새벽별 = 저녁별&quot;, &quot;번개 = 전기 방전&quot;, &quot;물 = H₂O&quot;처럼, 두 표현이 가리키는 대상이 실제로는 하나라는 뜻일 뿐, 두 표현의 의미가 같다는 말은 아니다.</p><p>문제는 <strong>상관관계 자체가 동일성을 함축하지 않는다</strong>는 것이다 — 한 사람과 그의 그림자는 상관관계에 있지만 동일하지 않다. 그렇다면 상관관계에서 동일성으로 나아가려면 무엇이 더 필요한가? 이 강의는 세 가지 답변 전략을 차례로 살펴본다 — (1) 스마트: 이론 선택의 단순성 원리, (2) 암스트롱: 마음 상태 개념에 대한 인과적 분석, (3) 파피노: 인과에 대한 형이상학적 원리(인과논증).</p><h2 id="스마트-—-오캄의-면도날에-호소" tabindex="-1">스마트 — 오캄의 면도날에 호소 <a class="header-anchor" href="#스마트-—-오캄의-면도날에-호소" aria-label="Permalink to &quot;스마트 — 오캄의 면도날에 호소&quot;">​</a></h2><p>스마트(J. J. C. Smart)는 감각 경험에 초점을 맞춘다. 마음-두뇌 상관관계와 양립 가능한 두 이론이 있다.</p><ul><li><strong>동일론</strong>(&quot;두뇌-과정 이론&quot;)</li><li><strong>부수현상론(epiphenomenalism)</strong>: 마음 상태는 물리적 상태와 구분되며 물리적 상태에 의해 야기되지만, 마음 상태 자체는 물리적인 것에 아무 영향도 끼치지 못한다는 견해. 이 경우 심적 속성을 설명하는 법칙은 물리법칙 그물에 매달린 &quot;<strong>법칙적 부착물(nomological dangler)</strong>&quot;이 되어버린다.</li></ul><p>스마트는 <strong>오캄의 면도날(Occam&#39;s Razor)</strong> — &quot;다른 조건이 같다면 더 단순한 이론을 선택하라&quot; — 을 근거로 동일론을 선호한다. 물리학이 거의 모든 것을 해명하는데 감각의 발생만은 예외로 남아 &quot;괴상한 법칙적 부착물&quot;을 요구한다는 것이 믿기 어렵다는 것이다. 다만 이 원리에는 &quot;다른 조건이 같다면&quot;이라는 단서가 붙는다 — 동일시해서는 안 될 이유가 있다면 오캄의 면도날은 적용되지 않는다.</p><p><strong>동일론에 대한 반론과 스마트의 대응</strong></p><table tabindex="0"><thead><tr><th>반론</th><th>스마트의 대응</th></tr></thead><tbody><tr><td>신경생리학을 전혀 모르는 사람도 &quot;고통&quot;이라는 말을 이해하는 데 아무 문제가 없다</td><td>번역 가능성과 동일성의 혼동. &quot;새벽별=저녁별&quot;처럼 &quot;A=B&quot;는 우연적 진술일 수 있고, 누군가 A인 줄은 알면서 그것이 B인 줄은 모를 수 있다</td></tr><tr><td>(위 반론이 실은 속성이원론을 함축하는 것 아닌가? — 저녁별에 결부된 속성과 새벽별에 결부된 속성이 다르다는 것 아닌가)</td><td>마음 상태를 <strong>화제중립적(topic-neutral)</strong>으로 기술할 수 있다 — &quot;오렌지를 볼 때 벌어지는 일과 유사한 일이 벌어지고 있다&quot;처럼, 물리적인 것을 더 추상적으로 기술한 것일 뿐일 수 있다</td></tr><tr><td>노란 잔상(afterimage)은 노란색인데, 두뇌를 열어봐도 노란색은 없다</td><td>노랗다고 해야 할 것은 &quot;잔상을 보는 경험&quot; 자체가 아니라 잔상 그 자체다</td></tr></tbody></table><p>스마트는 마지막으로 동일론과 부수현상론 사이의 선택이 경험적 문제인지 검토한다. 사실 두 이론 모두 상관관계라는 가능한 모든 증거와 양립 가능하므로, 경험적 증거만으로는 선택이 불가능하다. 스마트는 이를 지구가 화석·지층까지 완벽하게 창조론적 각본대로 기원전 4000년에 창조되었다는(그러나 진화의 모든 &quot;증거&quot;까지 갖춘) 가설에 비유한다 — 반박 불가능하지만 절약과 단순성의 원리를 위반하므로 진지하게 받아들여지지 않는다는 것. 동일론에 대한 지지도 결국 이런 단순성 원리에 근거한 선택이라는 것이 스마트의 결론이다.</p><h2 id="암스트롱-—-성향에-대한-인과적-분석" tabindex="-1">암스트롱 — 성향에 대한 인과적 분석 <a class="header-anchor" href="#암스트롱-—-성향에-대한-인과적-분석" aria-label="Permalink to &quot;암스트롱 — 성향에 대한 인과적 분석&quot;">​</a></h2><p><strong>암스트롱(D. M. Armstrong)</strong>은 행동주의의 교훈을 제대로 이해하면 유물론(동일론)으로 자연스럽게 나아가게 된다고 본다.</p><blockquote><p>행동에의 성향으로서의 마음 상태 개념(개념적 분석) + 신경과학의 발견(경험적 발견) ⇒ 동일론</p></blockquote><p>암스트롱은 이원론 → 행동주의 → 동일론의 과정을 정-반-합의 변증법에 비유한다.</p><p><strong>행동주의 비판</strong>: 행동주의의 핵심 문제는, 마음 상태를 표현하는 행동이 전혀 일어나지 않을 때도 그 마음 상태가 여전히 진행 중일 수 있다는 것이다(&quot;화가 났지만 아무 사인도 보이지 않는 사람&quot;). 대부분의 행동주의자는 이를 완화하려 <strong>성향(disposition)/경향성(tendency)</strong>에 호소한다 — 라일에 따르면 &quot;성향적 속성을 갖는다는 것은 어떤 특정 상태에 있는 것이 아니라, 특정 조건이 성립하면 특정 상태·변화를 겪게 되기 마련이라는 것&quot;이다(예: &quot;x가 수용성이 있다&quot; = &quot;만약 x를 물에 넣으면 x는 녹을 것이다&quot; — 이는 x가 어떤 내적 상태에 있음을 함축하지 않는다).</p><p>암스트롱은 이 라일식 조건문 분석으로도 부족하다고 본다.</p><blockquote><p>&quot;내가 사유하고 있지만 내 사유가 아무런 행동을 일으키지 않을 때조차, 나의 사유를 구성하는 무언가가 내 안에서 벌어지고 있다는 것은 세상 어떤 것보다도 명명백백하다. … 그 진행되고 있는 것 자체가 나의 사유이다.&quot;</p></blockquote><p>즉 마음 상태는 (아직 만족되지 않은 조건 아래) 행동을 낳을 성향에 그치지 않고, 지금 이 순간 실제로 진행 중인 <strong>내적 상태</strong>라는 것.</p><p><strong>행동주의와 암스트롱의 차이</strong></p><table tabindex="0"><thead><tr><th></th><th>정의</th></tr></thead><tbody><tr><td>행동주의(라일)</td><td>x가 고통에 있다 =def 만약 x가 조건 C에 있다면, x는 행동 B를 할 것이다</td></tr><tr><td>암스트롱</td><td>x가 고통에 있다 =def x는 C라는 조건에서 행동 B를 하게끔 <strong>야기하는 내적 상태</strong>에 있다</td></tr></tbody></table><p>이렇게 마음 상태 개념을 행동의 <strong>내적 원인</strong>으로 이해하는 견해를 <strong>마음에 대한 인과이론(causal theory of mind)</strong>이라 부른다(암스트롱, 데이비드 루이스 등이 대표적 지지자). 다만 이 이론도 행동주의에 대한 또 다른 중대한 반론 — 대부분의 경우 하나의 마음 상태는 다른 마음 상태와 결합해야 행동을 낳는다는 것 — 에는 별다른 해결책을 제시하지 못한다.</p><p><strong>인과적 분석에서 동일론으로</strong>: 마음에 대한 인과이론 자체는 논리적으로 유물론을 함축하지 않는다(원인이 되는 내적 상태가 데카르트가 말한 영적 실체일 가능성도 논리적으로는 남아 있다). 그러나 현대 과학은 실제로 그 내적 원인이 중추신경계의 물리-화학적 상태임을 밝혀냈다. 이로부터 다음 추론이 성립한다.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>P1</td><td>고통 = 조건 C에서 행동 B를 야기하는 상태 [개념적 분석]</td></tr><tr><td>P2</td><td>조건 C에서 행동 B를 야기하는 상태 = 두뇌 상태 N [과학적 연구]</td></tr><tr><td>C</td><td>따라서 고통 = 두뇌 상태 N</td></tr></tbody></table><p>스마트에게 동일성은 (단순성 원리에 의해) <strong>가정되는</strong> 것이었던 데 반해, 암스트롱의 인과이론에서 동일성은 개념 분석과 경험적 결과가 주어지면 <strong>논리적으로 강요되는</strong> 것이라는 차이가 있다.</p><p><strong>남는 문제 — 다중 실현 가능성의 예고</strong>: 고통을 느낄 수 있는 서로 다른 두 생물종(예: 문어와 사람)을 비교해 보자. 만약 두 종에서 고통에 전형적인 행동을 야기하는 두뇌 상태가 서로 다르다면? (이 문제는 다음 강의의 <strong>기능주의</strong>와 다중 실현 논증으로 이어진다.)</p><h2 id="파피노-—-유물론에-대한-인과논증" tabindex="-1">파피노 — 유물론에 대한 인과논증 <a class="header-anchor" href="#파피노-—-유물론에-대한-인과논증" aria-label="Permalink to &quot;파피노 — 유물론에 대한 인과논증&quot;">​</a></h2><p><strong>파피노(David Papineau)</strong>의 <strong>인과논증(causal argument)</strong>은 세 전제로 구성된다(원래 한국계 철학자 <strong>김재권(Jaegwon Kim)</strong>이 체계적으로 처음 제시한 논증이기도 하다).</p><table tabindex="0"><thead><tr><th>전제</th><th>내용</th></tr></thead><tbody><tr><td>(1) 심신인과(mental causation)</td><td>심적 상태(사건)는 물리적 결과를 갖는다</td></tr><tr><td>(2) 물리학의 완전성(completeness of physics)</td><td>모든 물리적 결과는 순전히 물리적인 인과적 역사로부터 온전히 야기된다</td></tr><tr><td>(3) 인과적 배제 원리</td><td>하나의 사건은 (특수한 경우를 제외하고) 두 개의 독립적 원인에 의해 과잉결정되지 않는다</td></tr></tbody></table><p>(1)을 받아들이면 (2)에 의해 하나의 물리적 결과(예: &quot;아야!&quot;라는 발화)에 정신적 원인(고통)과 물리적 원인(두뇌 상태) 두 가지가 있다는 것이 따라 나온다. 이것이 <strong>과잉결정(overdetermination)</strong>의 사례(예: 총과 벼락에 동시에 맞아 사망)가 아니라면 (3)에 의해 불가능하다. (1)~(3)을 모두 받아들이면서 이 딜레마를 피하는 유일한 길은 정신적 원인과 물리적 원인을 <strong>동일시</strong>하는 것뿐이다.</p><p>각 전제를 부정하는 대안들과 파피노의 반론은 다음과 같다.</p><p><strong>(1) 심신인과를 부정하는 경우</strong></p><ul><li><strong>예정조화설(pre-established harmony)</strong>: 라이프니츠가 발전시킨 견해로, 마음과 두뇌 사이에 실제 인과적 상호작용은 없으나 신이 미리 둘이 &quot;조화롭게&quot; 움직이도록 정해 놓았다는 것.</li><li><strong>부수현상론(epiphenomenalism)</strong>: 심적 사건은 두뇌 상태에서 발생하지만 그 자체로는 아무 인과적 효력이 없다는 것. (질적 마음 상태에 관해서는 오늘날에도 이 입장을 취하는 철학자들이 있다.)</li></ul><p>파피노는 두 이유로 부수현상론을 거부한다 — ①자연 어느 영역에서도 이런 &quot;인과적 부착물&quot;이 발견된 바 없다, ②동일한 현상을 똑같이 잘 설명하는 두 이론이 있다면 더 단순한 쪽을 선택해야 한다(단순성 원리). 다만 부수현상론이 비정합적(incoherent)이라고까지는 보지 않는다 — 다른 철학자들은 그 정합성 자체를 의심한다. (인식론의 <strong>인과이론</strong>에 따르면 우리가 심적 상태에 대해 인식적 접근을 가지려면 그 상태와 인과관계를 맺어야 하는데, 부수현상론에서는 심적 상태가 아무 인과적 효력이 없으므로 애초에 그것을 어떻게 알 수 있는지가 문제된다.)</p><p><strong>(3) 인과적 배제 원리를 부정하는 경우 — &quot;허리띠와 멜빵&quot;</strong></p><p>파피노는 이 입장을 &quot;<strong>허리띠와 멜빵(belt and brace)</strong>&quot; 견해라 부른다. 두 충분원인이 서로 완전히 <strong>독립적</strong>인 경우에는 배제 원리가 그럴듯하지만, 서로 <strong>의존 관계</strong>에 있는 경우엔 반례가 있을 수 있다.</p><ul><li>138kg인 철수가 100kg 이상이면 고장 나도록 설계된 체중계에 올라서서 체중계가 고장 났다. 원인은 &quot;100kg 이상이라는 사실&quot;인가, &quot;138kg이라는 사실&quot;인가?</li><li>진홍색 천을 흔들어 소가 흥분했다. 원인은 &quot;빨간색이라는 사실&quot;인가, &quot;진홍색이라는 사실&quot;인가?</li></ul><p>두 경우 모두 두 &quot;원인&quot;은 서로 다른 속성이지만 경쟁 관계라기보다는 특수한 의존 관계에 있다. 마음 상태와 두뇌 상태의 관계도 이와 같다면 서로 경쟁하는 두 원인이 아닐 수 있다(이런 관점은 다음 강의의 <strong>기능주의</strong>와도 통한다). 다만 이런 식으로 (속성)이원론을 살려도, 이것이 진정한 의미의 이원론인지는 의문이 남는다 — 상이한 두 속성이 아니라, 하나의 사실에 대한 상이한 <strong>기술(description)</strong>·<strong>개념(concept)</strong>이 있을 뿐이지 않은가.</p><p><strong>(2) 물리학의 완전성 재고</strong>: &quot;물리학&quot;의 의미를 고정하지 않으면 이 전제는 공허해진다(미래의 물리학이 정신적 속성을 포함하게 된다면?). 파피노는 이를 &quot;비생명적인 것(inanimate)&quot;으로 이해하며, 양자역학(독특한 화학적 힘의 부재 입증)과 DNA의 발견(독특한 생물학적 힘의 부재 입증) 등 20세기 과학의 발전이 물리학의 완전성을 귀납적으로 뒷받침한다고 본다. 다만 이는 어디까지나 귀납 논증이며, 반대자는 이런 귀납 추론 자체가 인간을 여느 물리적 대상과 마찬가지로 다룬다는 점에서 <strong>선결문제 요구의 오류</strong>를 범할 수 있다고 비판할 수 있다.</p><p>파피노는 인과논증의 결론이 (단순히 개념 분석만으로는 얻어지지 않는) <strong>존재적(existential)</strong> 주장임을 강조한다 — 특정 마음 상태와 특정 두뇌 상태의 동일성을 확립하려면, 과학이 밝히는 상관관계와 그 상관관계가 동일성 관계임을 보이는 철학적 논증이 모두 필요하다는 것. 이 점에서 인과논증은 스마트의 단순성 논증, 암스트롱의 개념 분석과 함께 심신동일론을 뒷받침하는 세 번째 독자적 경로를 이룬다.</p>',40)])])}const h=o(e,[["render",a]]);export{q as __pageData,h as default};
